  const d=[{"questions":[{"audit":{"id":"W01-Q01","blueprint":"3.A","sourceIds":["allergy"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q02","blueprint":"1.C.4","sourceIds":["metric"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q03","blueprint":"1.A.2","sourceIds":["pk"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q04","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W01-Q05","blueprint":"3.A","sourceIds":["recon"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q06","blueprint":"2.A.3","sourceIds":["tablet"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q07","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W01-Q08","blueprint":"3.A","sourceIds":["recon"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q09","blueprint":"1.C","sourceIds":["math"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q10","blueprint":"1.F","sourceIds":["label"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W01-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W01-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W01-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical suspension contains 40 mg/mL. What volume supplies 180 mg? Enter a number in mL.","answer":4.5,"unit":"mL","why":"180 mg ÷ 40 mg/mL = 4.5 mL. This is arithmetic practice, not a dosing recommendation.","audit":{"id":"W01-Q14","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which details help evaluate a reported penicillin reaction? Select all that apply.","options":["The suspected drug and when it was taken","The symptoms or reaction experienced","How long ago the reaction occurred","The color of the pharmacy walls"],"correct":[0,1,2],"why":"The specific medication, reaction, and timing help characterize the history. Further evaluation depends on the circumstances.","audit":{"id":"W01-Q15","blueprint":"3.A","sourceIds":["allergy"],"kind":"source_check","checked":"2026-10-28"}},{"type":"multiple","q":"What should be checked before substituting a biosimilar for its reference product? Select all that apply.","options":["The specific product’s FDA status","Applicable state substitution requirements","The relevant prescription and patient circumstances","Assume every biosimilar is automatically substitutable everywhere"],"correct":[0,1,2],"why":"Biosimilar and interchangeable-biosimilar determinations are product specific; substitution also depends on applicable state law and the prescription.","audit":{"id":"W01-Q16","blueprint":"2.B","sourceIds":["biosimilars"],"kind":"source_check","checked":"2026-10-28"}},{"q":"An order says metoprolol 50 mg daily but does not identify the salt or release form. The history lists an extended-release product. What is the best next step?","options":["Choose whichever product is in stock","Clarify the intended product and formulation","Dispense both formulations","Assume all forms have identical directions"],"correct":1,"why":"The intended salt and dosage form should be confirmed; product-specific formulations and directions differ.","audit":{"id":"W01-Q17","blueprint":"2.A.3","sourceIds":["metoprololER","label"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A handwritten insulin order includes a dose followed by an unclear “U.” What should the pharmacist do before processing it?","options":["Interpret the mark as zero","Use the previous dose without checking","Clarify the dose and document the unit clearly","Convert the dose into milliliters without verifying concentration"],"correct":2,"why":"“U” is an error-prone abbreviation. Clarify the actual dose and express units unambiguously.","audit":{"id":"W01-Q18","blueprint":"2.A.2","sourceIds":["abbreviation","insulin"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient requests a generic for an oral brand-name tablet. Which comparison best supports a product check?","options":["Active ingredient, strength, dosage form and route","Bottle size and tablet color only","The first three letters of the name","Price without reviewing the product"],"correct":0,"why":"An approved generic is evaluated for relevant sameness, including active ingredient, strength, dosage form and route. Check applicable substitution rules.","audit":{"id":"W01-Q19","blueprint":"2.B","sourceIds":["orangeBook"],"kind":"source_check","checked":"2026-10-28"}},{"q":"An older medication record lists Zestril, while a new record lists lisinopril. Which identification is correct?","options":["They are two unrelated anticoagulants","Zestril contains lisinopril, an ACE inhibitor","Lisinopril is a loop diuretic","Zestril is a type of insulin"],"correct":1,"why":"The cited Zestril label identifies lisinopril as its active ingredient and classifies it as an ACE inhibitor.","audit":{"id":"W01-Q20","blueprint":"2.A.1","sourceIds":["zestril"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.A"},{"blueprint":"1.A.2"},{"blueprint":"1.C"},{"blueprint":"2.A"},{"blueprint":"1.F / 2.B","points":["Product labeling provides indication, dosing, contraindications, warnings, interactions and administration details; check the current label for the specific product.","Immediate-release and extended-release products may have different instructions. Do not assume a modified-release tablet can be crushed or substituted on a milligram-for-milligram basis.","When sources differ, consider publication dates, the question being asked, patient-specific factors and the strength of evidence.","Biosimilar substitution depends on the specific product’s FDA status, the prescription, and applicable state law."]}],"medicationFocus":{"title":"Interpreting orders and product names","blueprint":"2.A.1 / 2.A.2 / 2.A.3","intro":"Read the complete order and identify the exact product before processing it.","points":["Compare the generic name, strength, formulation, route, directions, quantity and intended use; clarify contradictions rather than guessing.","Immediate-release and extended-release formulations are not automatically interchangeable. Verify the prescribed formulation and its product-specific administration instructions.","Check generic equivalence and any applicable substitution requirements. Write units clearly and avoid error-prone abbreviations and decimal notation."],"sourceIds":["label","metoprololER","orangeBook","abbreviation"]},"math":{"title":"Dose from a liquid concentration","prompt":"A prescription calls for 500 mg. The liquid contains 250 mg per 5 mL. How many mL supply one dose?","steps":["Set up 500 mg × (5 mL ÷ 250 mg).","Cancel mg and calculate 500 × 5 ÷ 250."],"answer":"10 mL"},"sources":[{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"},{"name":"CDC medication safety","url":"https://www.cdc.gov/medication-safety/data-research/facts-stats/"},{"name":"FDA: biosimilars and interchangeability","url":"https://www.fda.gov/drugs/biosimilars/9-things-know-about-biosimilars-and-interchangeable-biosimilars"}]},{"questions":[{"audit":{"id":"W02-Q01","blueprint":"3.D.2","sourceIds":["warfarin"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q02","blueprint":"3.C.5","sourceIds":["ace"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q03","blueprint":"3.C.3","sourceIds":["warfarin","apixaban"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q04","blueprint":"3.D.2","sourceIds":["ace"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q05","blueprint":"3.D","sourceIds":["hf"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q06","blueprint":"3.C.2","sourceIds":["furosemide"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q07","blueprint":"1.A.1","sourceIds":["antithrombotic"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q08","blueprint":"3.D.2","sourceIds":["warfarin"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q09","blueprint":"3.C.2","sourceIds":["apixaban"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q10","blueprint":"3.D","sourceIds":["hf"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W02-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W02-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W02-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical infusion is ordered at 0.05 mg/kg/hour for an 80 kg patient. How many mg per hour is that?","answer":4,"unit":"mg/hour","why":"0.05 mg/kg/hour × 80 kg = 4 mg/hour. This is arithmetic practice, not a treatment recommendation.","audit":{"id":"W02-Q14","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which findings merit review for a person taking warfarin? Select all that apply.","options":["A recent INR result","A newly started antibiotic","An unexplained black, tarry stool","Only the tablet color, without reviewing the medicine"],"correct":[0,1,2],"why":"INR, possible bleeding, and interacting medicines are important. A possible serious bleed requires prompt clinical assessment.","audit":{"id":"W02-Q15","blueprint":"3.D.2","sourceIds":["warfarin"],"kind":"source_check","checked":"2026-10-28"}},{"type":"numeric","q":"For a simplified nutrition calculation, a formula contains 100 g of digestible carbohydrate, providing 4 kcal per gram. How many kcal are supplied by that carbohydrate?","answer":400,"unit":"kcal","why":"100 g × 4 kcal/g = 400 kcal. This exercise does not determine an individual patient’s nutrition needs.","audit":{"id":"W02-Q16","blueprint":"1.C.7","sourceIds":["nutrition"],"kind":"independent_calculation","checked":"2026-10-28"}},{"q":"A person with nonvalvular atrial fibrillation is 82 years old, weighs 58 kg and has serum creatinine of 1.6 mg/dL. A new apixaban order is for 5 mg twice daily. What is the best dispensing review?","options":["Verify the indication and contact the prescriber about the dose","Dispense 5 mg twice daily without checking the label","Automatically replace apixaban with warfarin","Double the dose because the patient is older"],"correct":0,"why":"For this indication, the cited apixaban label specifies 2.5 mg twice daily when at least two of the listed age, weight and serum-creatinine criteria are met. Verify the complete patient and product information with the prescriber.","audit":{"id":"W02-Q17","blueprint":"2.A.5","sourceIds":["apixaban"],"kind":"source_check","checked":"2026-10-28"}},{"q":"An apixaban prescription arrives without an indication, and the patient has kidney impairment. Why is the indication needed?","options":["Only the insurance plan uses it","Dosing and assessment can differ by indication and patient factors","All apixaban indications use the same regimen","It determines the tablet color"],"correct":1,"why":"Apixaban labeling distinguishes regimens by indication and patient characteristics. Obtain the missing information and review interactions and kidney function.","audit":{"id":"W02-Q18","blueprint":"2.A.2","sourceIds":["apixaban"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient plans to keep nitroglycerin sublingual tablets in a weekly pill organizer. What does the cited label advise?","options":["Store tablets loose in a warm bathroom","Transfer them to any open container","Keep them in the original glass container, tightly capped","Freeze the tablets after every use"],"correct":2,"why":"The cited nitroglycerin sublingual tablet label specifies the original glass container, tightly capped, to protect potency.","audit":{"id":"W02-Q19","blueprint":"2.D","sourceIds":["nitroglycerin"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A person on lisinopril has a new high potassium result in the pharmacy record. What should the pharmacist do?","options":["Ignore it if the blood pressure is controlled","Recommend a potassium supplement","Assume the lab is unrelated to treatment","Evaluate and communicate the result according to the care plan before continuing routine processing"],"correct":3,"why":"ACE inhibitors can affect potassium and kidney function. A concerning result warrants clinical review and communication.","audit":{"id":"W02-Q20","blueprint":"2.A.5","sourceIds":["ace"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C"},{"blueprint":"3.D"},{"blueprint":"3.C.3"},{"blueprint":"3.C.2"},{"blueprint":"3.D"}],"medicationFocus":{"title":"Cardiovascular prescriptions and safety checks","blueprint":"2.A.2 / 2.A.5 / 2.D","intro":"A dose must fit both the specific product and the patient.","points":["For apixaban, check the indication and current label: dose adjustments are indication-specific, and age, weight, serum creatinine and interactions may matter.","Review relevant safety information, including bleeding risk for anticoagulants and kidney function and potassium for ACE inhibitors.","Follow product-specific storage: the cited nitroglycerin sublingual tablet label calls for its original tightly capped glass container."],"sourceIds":["apixaban","ace","nitroglycerin"]},"math":{"title":"Weight-based infusion","prompt":"An order is for 5 micrograms/kg/min for an 80 kg patient. How many micrograms per minute is this?","steps":["Multiply 5 micrograms/kg/min × 80 kg.","Cancel kg and retain micrograms per minute."],"answer":"400 micrograms/min"},"sources":[{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"},{"name":"CDC medication safety","url":"https://www.cdc.gov/medication-safety/data-research/facts-stats/"},{"name":"MedlinePlus: warfarin","url":"https://medlineplus.gov/druginfo/meds/a682277.html"},{"name":"MedlinePlus: lisinopril","url":"https://medlineplus.gov/druginfo/meds/a692051.html"}]},{"questions":[{"audit":{"id":"W03-Q01","blueprint":"3.C.5","sourceIds":["lowglucose"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W03-Q02","blueprint":"3.B","sourceIds":["kidney"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W03-Q03","blueprint":"3.C.2","sourceIds":["type1"],"kind":"source_check","checked":"2026-10-28"},"q":"Which type of diabetes generally requires insulin treatment?","why":"Most people with type 1 diabetes need insulin every day. Treatment for other forms depends on individual circumstances."},{"audit":{"id":"W03-Q04","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W03-Q05","blueprint":"3.C.3","sourceIds":["thyroid"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W03-Q06","blueprint":"2.A.3","sourceIds":["insulin","insulin300"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W03-Q07","blueprint":"3.C.2","sourceIds":["diabetes"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W03-Q08","blueprint":"3.B","sourceIds":["kidney"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W03-Q09","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W03-Q10","blueprint":"3.E.2","sourceIds":["thyroid"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W03-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W03-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W03-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical U-100 insulin solution contains 100 units/mL. What volume contains 35 units? Enter a number in mL.","answer":0.35,"unit":"mL","why":"35 units ÷ 100 units/mL = 0.35 mL. This is a concentration exercise; follow the specific product and device instructions in practice.","audit":{"id":"W03-Q14","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which can be symptoms of low blood glucose? Select all that apply.","options":["Shakiness","Sweating","Confusion","A guarantee that there will be no symptoms"],"correct":[0,1,2],"why":"Low blood glucose can cause shakiness, sweating, or confusion; symptoms and treatment must be assessed in context.","audit":{"id":"W03-Q15","blueprint":"3.C.5","sourceIds":["lowglucose"],"kind":"source_check","checked":"2026-10-28"}},{"type":"numeric","q":"A hypothetical drug follows first-order elimination, with no additional doses. Its concentration is 80 mg/L. What is the concentration after two half-lives?","answer":20,"unit":"mg/L","why":"The concentration falls from 80 to 40 mg/L after one half-life, then to 20 mg/L after a second. The stated first-order assumption matters.","audit":{"id":"W03-Q16","blueprint":"1.C.9","sourceIds":["halflife"],"kind":"independent_calculation","checked":"2026-10-28"}},{"q":"A person has a Toujeo U-300 insulin pen and asks to withdraw a dose from the pen using a U-100 syringe. What does the product label instruct?","options":["Do not withdraw Toujeo from the pen with a syringe","Withdraw any volume using a U-100 scale","Dilute the pen contents first","Share the pen with another person after changing the needle"],"correct":0,"why":"The cited Toujeo label warns not to use a syringe to remove insulin from the pen because an overdose can result. Follow the device instructions.","audit":{"id":"W03-Q17","blueprint":"2.A.3","sourceIds":["insulin300"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A new metformin extended-release prescription is received for a patient whose recent eGFR is 25 mL/min/1.73 m². What is the best next step?","options":["Fill it routinely without reviewing the result","Hold processing and discuss the contraindication with the prescriber","Increase the dose to compensate","Treat the result as irrelevant because this is an extended-release tablet"],"correct":1,"why":"The cited metformin extended-release label contraindicates use when eGFR is below 30 mL/min/1.73 m². Confirm the result and discuss the order with the prescriber.","audit":{"id":"W03-Q18","blueprint":"2.A.5","sourceIds":["metforminER"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient cannot swallow the prescribed metformin extended-release tablet and asks to crush it. What should be done?","options":["Crush it because all tablets may be crushed","Chew it only on alternate days","Review the label and discuss an appropriate alternative with the prescriber","Replace it with any product at the same tablet count"],"correct":2,"why":"The cited extended-release label instructs patients to swallow the tablet whole and not crush, cut or chew it. Discuss an appropriate alternative.","audit":{"id":"W03-Q19","blueprint":"2.A.3","sourceIds":["metforminER"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A pharmacy is considering a biosimilar insulin substitution. Which information is necessary?","options":["Only the package color","Only the manufacturer name","The patient’s preferred injection time","The specific product’s FDA status, the order and applicable state law"],"correct":3,"why":"Biosimilar and interchangeable status is specific to the product; applicable substitution requirements and the prescription also matter.","audit":{"id":"W03-Q20","blueprint":"2.B","sourceIds":["biosimilars","purpleBook"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C.2","points":["Most people with type 1 diabetes need insulin every day. People with type 2 diabetes may use a variety of medicines, including insulin, depending on their circumstances.","Insulin products differ in concentration, onset and duration. Verify the exact product and device; mix-ups can cause serious harm.","Hypoglycemia is a key safety issue with insulin and certain other diabetes medicines. Review recognition, treatment, prevention, and follow-up using a current clinical reference."]},{"blueprint":"3.B"},{"blueprint":"3.D"},{"blueprint":"3.C.2"},{"blueprint":"3.C.2"}],"medicationFocus":{"title":"Insulin and diabetes product checks","blueprint":"2.A.3 / 2.A.5 / 2.B","intro":"Check the exact concentration, device and formulation for each order.","points":["Insulin products and devices vary in concentration and use. Check the name and label before each administration; follow the instructions for the exact device.","Some metformin extended-release products must be swallowed whole. Their labels specify kidney-function contraindications; verify the current label and patient information.","A proposed biologic substitution requires verification of the specific product, FDA status, the prescription and applicable state requirements."],"sourceIds":["insulin300","metforminER","biosimilars"]},"math":{"title":"Insulin concentration","prompt":"An insulin contains 100 units/mL. What volume contains 25 units?","steps":["25 units × (1 mL ÷ 100 units).","Cancel units and calculate 25 ÷ 100."],"answer":"0.25 mL"},"sources":[{"name":"NIDDK diabetes medicines and treatment","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/insulin-medicines-treatments"},{"name":"NIDDK kidney function and eGFR","url":"https://www.niddk.nih.gov/research-funding/research-programs/kidney-clinical-research-epidemiology/laboratory/factors-affecting-egfr-accuracy/clinical-measurements"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"}]},{"questions":[{"audit":{"id":"W04-Q01","blueprint":"3.D","sourceIds":["abxreview"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q02","blueprint":"3.C.2","sourceIds":["cold"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q03","blueprint":"3.A","sourceIds":["allergy"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q04","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W04-Q05","blueprint":"4.B","sourceIds":["abx"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q06","blueprint":"3.C.3","sourceIds":["doxy"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q07","blueprint":"3.D","sourceIds":["abxreview"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q08","blueprint":"3.A","sourceIds":["allergy"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q09","blueprint":"3.D","sourceIds":["abx"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q10","blueprint":"4.B","sourceIds":["abx"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W04-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W04-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W04-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical order is 6 mg/kg per dose for a person weighing 42 kg. How many mg are in one dose?","answer":252,"unit":"mg","why":"6 mg/kg × 42 kg = 252 mg per dose. The order is hypothetical and does not establish an appropriate medication dose.","audit":{"id":"W04-Q14","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which actions support antibiotic stewardship? Select all that apply.","options":["Review the indication for treatment","Reassess when culture results and clinical response are available","Clarify the drug and reaction in an allergy history","Continue every broad-spectrum regimen unchanged regardless of evidence"],"correct":[0,1,2],"why":"Appropriate use includes evaluating the indication, the allergy history, and opportunities to reassess treatment.","audit":{"id":"W04-Q15","blueprint":"4.B","sourceIds":["abx","abxreview","allergy"],"kind":"source_check","checked":"2026-10-28"}},{"type":"numeric","q":"An arithmetic exercise asks for 100 mL of a 0.5% w/v preparation. How many grams of ingredient are needed?","answer":0.5,"unit":"g","why":"0.5% w/v means 0.5 g per 100 mL. This calculation alone does not establish a safe or stable preparation.","audit":{"id":"W04-Q16","blueprint":"1.C.6","sourceIds":["math","compound"],"kind":"independent_calculation","checked":"2026-10-28"}},{"q":"A patient has a new doxycycline order and takes an iron supplement at the same time. What should the pharmacist review?","options":["The supplement can impair absorption; consult the product-specific instructions","Iron always improves antibiotic absorption","Only the color of the supplement","Whether the antibiotic is stored in alphabetical order"],"correct":0,"why":"The cited doxycycline labeling notes impaired absorption with iron and certain antacids. Check product-specific instructions and the patient’s regimen.","audit":{"id":"W04-Q17","blueprint":"2.A.5","sourceIds":["doxy"],"kind":"source_check","checked":"2026-10-28"}},{"q":"An antibiotic prescription is received with directions “twice daily” and “every 8 hours.” What is the safest next step?","options":["Use the longer interval without asking","Clarify the intended frequency with the prescriber","Print both directions for the patient to choose","Remove both directions from the label"],"correct":1,"why":"Twice daily and every 8 hours are different schedules. Resolve conflicting instructions before processing.","audit":{"id":"W04-Q18","blueprint":"2.A.2","sourceIds":["abbreviation","label"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient reports a previous serious reaction to an antibiotic, but the order does not include the allergy details. What should be done?","options":["Assume all reported allergies are mild","Ignore the history if the prescription is electronic","Clarify the drug, reaction and timing before completing the review","Change the prescription without consulting the prescriber"],"correct":2,"why":"The specific medication and nature and timing of the reaction help the care team evaluate an allergy report.","audit":{"id":"W04-Q19","blueprint":"2.A.5","sourceIds":["allergy"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A discharge list and a new antibiotic prescription show different durations. Which action fits medication-order review?","options":["Use whichever duration is shorter without checking","Dispense both courses","Delete the discharge list","Reconcile the discrepancy and clarify the intended duration"],"correct":3,"why":"A disagreement between medication sources is a discrepancy to reconcile with the appropriate care team.","audit":{"id":"W04-Q20","blueprint":"2.A.2","sourceIds":["recon","abxreview"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C.2"},{"blueprint":"3.C.5"},{"blueprint":"3.D"},{"blueprint":"3.D"},{"blueprint":"3.C.3"}],"medicationFocus":{"title":"Antimicrobial order review","blueprint":"2.A.2 / 2.A.5","intro":"Reconcile the order, allergy history and administration instructions.","points":["Check the drug, indication, dose, route, interval, duration, allergy history and relevant lab data; clarify contradictory directions.","Doxycycline absorption can be impaired by certain mineral-containing products. Check the actual product label and the complete medication list.","Review an antibiotic order against the current plan and available culture information; changes require an authorized prescriber or applicable protocol."],"sourceIds":["doxy","allergy","abxreview","recon"]},"math":{"title":"Infusion rate","prompt":"An infusion contains 100 mL and is to run over 30 minutes. What pump rate in mL/hour is needed?","steps":["Convert 30 minutes to 0.5 hour.","Divide 100 mL by 0.5 hour."],"answer":"200 mL/hour"},"sources":[{"name":"CDC antibiotic stewardship","url":"https://www.cdc.gov/antibiotic-use/hcp/core-elements/outpatient-antibiotic-stewardship.html"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"},{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"MedlinePlus: doxycycline","url":"https://medlineplus.gov/druginfo/meds/a682063.html"}]},{"questions":[{"audit":{"id":"W05-Q01","blueprint":"3.D.3","sourceIds":["hiv"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q02","blueprint":"2.C","sourceIds":["vaccine"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q03","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W05-Q04","blueprint":"3.C.2","sourceIds":["hiv"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q05","blueprint":"4.A","sourceIds":["vaers"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q06","blueprint":"3.C.7","sourceIds":["hiv"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q07","blueprint":"2.C.1","sourceIds":["vaccineschedule"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q08","blueprint":"3.C.3","sourceIds":["hivinteractions"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q09","blueprint":"2.C","sourceIds":["vaccine"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q10","blueprint":"4.A","sourceIds":["vaers"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W05-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W05-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W05-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"For an arithmetic exercise, 8 hypothetical doses each use 0.5 mL. How many mL total are needed, ignoring waste and vial restrictions?","answer":4,"unit":"mL","why":"8 × 0.5 mL = 4 mL. Actual vaccine preparation and vial requirements are product-specific.","audit":{"id":"W05-Q14","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which checks belong in an immunization workflow? Select all that apply.","options":["Review vaccine history and eligibility","Screen for contraindications and precautions","Check the correct product and route","Skip documentation if the patient feels well"],"correct":[0,1,2],"why":"History, screening, the correct product and route, and documentation all matter. Use the current schedule and product guidance.","audit":{"id":"W05-Q15","blueprint":"2.C","sourceIds":["vaccine","vaccineschedule"],"kind":"source_check","checked":"2026-10-28"}},{"type":"multiple","q":"A vaccine refrigerator temperature has gone outside the product’s recommended range. Which actions are appropriate? Select all that apply.","options":["Notify the vaccine coordinator or supervisor","Mark affected vaccines as do not use and separate them as directed","Document the event and seek product-specific guidance","Assume the vaccines are usable because the vials look normal"],"correct":[0,1,2],"why":"Follow the facility’s excursion procedure and obtain guidance from the immunization program or manufacturer. Do not assume visual appearance establishes viability.","audit":{"id":"W05-Q16","blueprint":"2.D","sourceIds":["storage"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient reports anaphylaxis immediately after a previous dose of the same vaccine. What should occur before another dose?","options":["Proceed because all vaccine reactions are harmless","Treat the history as a potential contraindication and evaluate it","Give a double dose to compensate","Rely only on the patient’s age"],"correct":1,"why":"A severe allergic reaction after a prior dose can be a contraindication. Check the specific vaccine and current guidance.","audit":{"id":"W05-Q17","blueprint":"2.C.2","sourceIds":["contraindications"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A vaccine vial has passed the expiration date printed by its manufacturer. What should the vaccinator do?","options":["Use it if the liquid looks clear","Use it if the patient is an adult","Do not administer the expired vaccine","Mix it with an unexpired vial"],"correct":2,"why":"CDC advises against using expired vaccine, diluent or equipment. Follow the site’s handling and disposal procedures.","audit":{"id":"W05-Q18","blueprint":"2.C.3","sourceIds":["vaccineDuring"],"kind":"source_check","checked":"2026-10-28"}},{"q":"Before a tetanus-containing vaccine covered by the VIS requirement is given, which action is appropriate?","options":["Provide the current VIS and document the required information","Provide a VIS only after a serious reaction","Record only the patient’s first name","Skip documentation if the vaccine was given at a pharmacy"],"correct":0,"why":"For covered vaccines, CDC describes providing the current VIS before each dose and recording required information, including VIS and vaccine details.","audit":{"id":"W05-Q19","blueprint":"2.C","sourceIds":["vaccineVIS"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A lyophilized vaccine requires reconstitution. Which diluent should be used?","options":["Any available sterile water","Any vaccine diluent with a similar volume","Normal saline whenever it is convenient","The specific diluent supplied for that vaccine, following manufacturer instructions"],"correct":3,"why":"CDC says to use the manufacturer-supplied, product-specific diluent and follow the vaccine’s reconstitution and use instructions.","audit":{"id":"W05-Q20","blueprint":"2.C.4","sourceIds":["vaccineMix"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C.2"},{"blueprint":"3.C"},{"blueprint":"2.C"},{"blueprint":"3.C.3"},{"blueprint":"2.C"}],"medicationFocus":{"title":"Immunization workflow","blueprint":"2.C.1 / 2.C.2 / 2.C.3 / 2.C.4 / 2.C.5","intro":"Work through screening, preparation, administration and documentation for the specific vaccine.","points":["Check current recommendations, prior doses, age, relevant contraindications and precautions before each dose.","Verify product, expiration, storage, route and any required product-specific diluent. Follow instructions for reconstitution and the usable period.","For vaccines covered by the VIS requirement, provide the current VIS before the dose and document the required details. Follow applicable reporting requirements for adverse events."],"sourceIds":["vaccineschedule","contraindications","vaccineDuring","vaccineMix","vaccineVIS","vaccineReports"]},"math":{"title":"Pediatric dose","prompt":"A practice order calls for 10 mg/kg per dose for a child weighing 18 kg. How many mg are needed per dose?","steps":["Multiply 10 mg/kg × 18 kg.","Cancel kg and retain mg per dose."],"answer":"180 mg per dose"},"sources":[{"name":"HIV clinical guidelines","url":"https://clinicalinfo.hiv.gov/en/guidelines"},{"name":"CDC adult immunization schedule","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-schedule-vaccines.html"},{"name":"Vaccine Adverse Event Reporting System","url":"https://vaers.hhs.gov/"}]},{"questions":[{"audit":{"id":"W06-Q01","blueprint":"3.E.2","sourceIds":["inhaled"],"kind":"source_check","checked":"2026-10-28"},"q":"Which action can reduce local oral adverse effects after fluticasone inhalation aerosol?","why":"The fluticasone inhalation aerosol label advises rinsing the mouth after use to reduce local oral effects. Follow the instructions for the specific product."},{"audit":{"id":"W06-Q02","blueprint":"3.D","sourceIds":["asthma"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W06-Q03","blueprint":"1.A.1","sourceIds":["ppi"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W06-Q04","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W06-Q05","blueprint":"3.F","sourceIds":["diarrhea"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W06-Q06","blueprint":"1.A.1","sourceIds":["albuterol"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W06-Q07","blueprint":"3.G","sourceIds":["asthma"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W06-Q08","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W06-Q09","blueprint":"3.F","sourceIds":["diarrhea"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W06-Q10","blueprint":"3.E.2","sourceIds":["inhaled"],"kind":"source_check","checked":"2026-10-28"},"q":"What counseling point appears in the fluticasone inhalation aerosol instructions?","why":"The fluticasone inhalation aerosol label advises rinsing the mouth after use to reduce local oral effects. Follow the instructions for the specific product."},{"audit":{"id":"W06-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W06-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W06-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"An exercise asks for 250 mL to infuse over 90 minutes. What is the pump rate in mL/hour, rounded to one decimal place?","answer":166.7,"unit":"mL/hour","why":"90 minutes is 1.5 hours. 250 ÷ 1.5 = 166.666… mL/hour, or 166.7 mL/hour to one decimal.","audit":{"id":"W06-Q14","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which steps are useful when reviewing an inhaled corticosteroid? Select all that apply.","options":["Check the person’s device technique","Review whether the medicine is being taken as prescribed","For a product that instructs it, rinse the mouth after inhalation","Assume all inhalers use identical technique"],"correct":[0,1,2],"why":"Technique and adherence affect treatment. Follow the specific product’s instructions; fluticasone labeling advises rinsing the mouth after use.","audit":{"id":"W06-Q15","blueprint":"3.G","sourceIds":["asthma","inhaled"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient uses fluticasone inhalation aerosol every day. What administration instruction appears in the cited label?","options":["Rinse the mouth with water after inhalation without swallowing","Use the inhaler only for a sudden attack","Share the device after wiping the mouthpiece","Stop maintenance therapy whenever symptoms improve"],"correct":0,"why":"The cited label advises rinsing the mouth without swallowing after use to reduce the risk of local oral candidiasis.","audit":{"id":"W06-Q16","blueprint":"2.A.2","sourceIds":["inhaled"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A new order describes albuterol inhalation aerosol as the patient’s sole long-term asthma control plan. Symptoms remain frequent. What should be reviewed?","options":["Only the inhaler color","The prescribed plan, symptoms, technique and need to discuss control with the prescriber","Assume frequent symptoms do not matter","Replace it with any inhaler without a new plan"],"correct":1,"why":"Albuterol has a quick-relief role; frequent symptoms warrant assessment of the plan, technique and adherence with the care team.","audit":{"id":"W06-Q17","blueprint":"2.A.5","sourceIds":["albuterol","asthma"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient receives a different inhaler device and says all inhalers are used identically. What is the best response?","options":["Confirm that all devices use exactly the same steps","Tell the patient to ignore the new instructions","Review and demonstrate the technique for the actual device","Discard the written instructions"],"correct":2,"why":"Technique is device-specific. Review the product’s instructions and assess how the person uses the actual inhaler.","audit":{"id":"W06-Q18","blueprint":"2.A.3","sourceIds":["asthma","inhaled"],"kind":"source_check","checked":"2026-10-28"}},{"q":"An inhaler order lists a drug and strength but no frequency. What should the pharmacist do?","options":["Invent a frequency based only on the label color","Use another patient’s directions","Write “as desired” without review","Clarify the missing directions using the prescriber’s order and the product information"],"correct":3,"why":"A complete order needs the intended directions. Clarify missing information rather than assuming the regimen.","audit":{"id":"W06-Q19","blueprint":"2.A.2","sourceIds":["label","inhaled"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C.2"},{"blueprint":"3.C.2"},{"blueprint":"3.D"},{"blueprint":"3.G"},{"blueprint":"3.F"}],"medicationFocus":{"title":"Inhaler product and order review","blueprint":"2.A.2 / 2.A.3 / 2.A.5","intro":"An inhaler order needs the right product, directions and device technique.","points":["Identify the inhaler, strength, device, route, intended role and directions; do not assume devices or formulations work identically.","Fluticasone inhalation aerosol is a maintenance product; its cited label recommends rinsing the mouth after inhalation without swallowing.","Albuterol inhalation aerosol has a different role. Review symptoms, the prescribed plan, technique and the product label when a regimen seems inconsistent."],"sourceIds":["inhaled","albuterol","asthma"]},"math":{"title":"Electrolyte quantity","prompt":"A solution contains 2 mEq of potassium per mL. How many mEq are in 15 mL?","steps":["Multiply 2 mEq/mL × 15 mL.","Cancel mL."],"answer":"30 mEq"},"sources":[{"name":"MedlinePlus asthma control medications","url":"https://www.medlineplus.gov/ency/patientinstructions/000005.htm"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"},{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"MedlinePlus: inhaler technique","url":"https://www.medlineplus.gov/druginfo/meds/a601172.html"}]},{"questions":[{"audit":{"id":"W07-Q01","blueprint":"3.D.2","sourceIds":["lithium"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q02","blueprint":"3.C.5","sourceIds":["opioids"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q03","blueprint":"1.A.1","sourceIds":["depression"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q04","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W07-Q05","blueprint":"3.C.6","sourceIds":["naloxone"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q06","blueprint":"3.C.3","sourceIds":["opioids"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q07","blueprint":"3.D.2","sourceIds":["lithium"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q08","blueprint":"3.C.6","sourceIds":["naloxone"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q09","blueprint":"3.C.5","sourceIds":["morphine"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q10","blueprint":"3.D","sourceIds":["depression"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W07-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W07-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W07-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical prescription is for 1.5 tablets twice daily for 14 days. How many tablets are needed?","answer":42,"unit":"tablets","why":"1.5 tablets × 2 doses/day × 14 days = 42 tablets.","audit":{"id":"W07-Q14","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"What steps are appropriate when opioid overdose is suspected? Select all that apply.","options":["Call emergency services","Give naloxone if available and follow instructions","Stay with the person until emergency help arrives","Assume medical care is unnecessary if the person wakes up"],"correct":[0,1,2],"why":"Naloxone can temporarily reverse opioid effects, but emergency help and continued observation remain important.","audit":{"id":"W07-Q15","blueprint":"3.C.6","sourceIds":["naloxone"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient has prescriptions for an opioid and a benzodiazepine from different clinicians. Which concern needs review?","options":["Potential additive sedation and respiratory depression","Only a possible change in tablet color","A guaranteed lack of interaction","The medicines must always be stopped immediately by the pharmacy"],"correct":0,"why":"FDA warns that combined opioid and benzodiazepine use can cause serious sedation and respiratory depression. Review the regimen and communicate with the care team.","audit":{"id":"W07-Q16","blueprint":"2.A.4","sourceIds":["opioids"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient asks what to do with unwanted medication. What is an appropriate starting point?","options":["Put every medicine in a recycling bin","Use a drug take-back option when available and check product-specific disposal instructions","Assume all medicines belong on the FDA flush list","Give the medicine to a friend"],"correct":1,"why":"FDA recommends take-back options for most unwanted medicines. If one is unavailable, follow the specific FDA and local disposal guidance.","audit":{"id":"W07-Q17","blueprint":"2.D","sourceIds":["disposal"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A lithium refill is requested, and the available record lacks recent monitoring information. Which step is appropriate?","options":["Assume levels are never necessary","Change the dose based only on capsule color","Review the treatment plan for serum concentration and kidney-function monitoring","Combine the refill with an extra interacting medicine"],"correct":2,"why":"Lithium requires individualized monitoring, including serum concentrations and kidney function, according to the clinical plan and current labeling.","audit":{"id":"W07-Q18","blueprint":"2.A.5","sourceIds":["lithium"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A prescription includes a boxed warning about combined sedating medicines. What is the best use of that warning?","options":["Ignore it if the medicine is familiar","Treat it as an indication to change the prescription without consultation","Read only the product advertisement","Review the specific risk, the patient’s other medicines and the prescriber’s plan"],"correct":3,"why":"A boxed warning is an important product-specific safety signal. Assess it in the full medication and patient context.","audit":{"id":"W07-Q19","blueprint":"2.A.4","sourceIds":["label","opioids"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C.2"},{"blueprint":"3.D"},{"blueprint":"3.C.6"},{"blueprint":"3.D"},{"blueprint":"3.C.6"}],"medicationFocus":{"title":"High-risk medicines and disposal","blueprint":"2.A.4 / 2.A.5 / 2.D","intro":"Confirm warnings, monitoring, storage and disposal for the actual medicine.","points":["Opioids and other central nervous system depressants can produce serious sedation and breathing risks. Assess the combination and communicate concerns.","Lithium regimens need individualized review of serum concentrations and kidney function according to the treatment plan.","For unwanted medicines, FDA recommends a take-back option for most products; check the specific disposal instructions and applicable local guidance."],"sourceIds":["opioids","lithium","disposal"]},"math":{"title":"Tablet quantity","prompt":"A prescription calls for 1.5 tablets per dose, taken twice daily for 10 days. How many tablets are needed?","steps":["1.5 tablets/dose × 2 doses/day = 3 tablets/day.","3 tablets/day × 10 days = 30 tablets."],"answer":"30 tablets"},"sources":[{"name":"NIMH mental health medications","url":"https://www.nimh.nih.gov/health/topics/mental-health-medications"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"},{"name":"CDC medication safety","url":"https://www.cdc.gov/medication-safety/data-research/facts-stats/"}]},{"questions":[{"audit":{"id":"W08-Q01","blueprint":"3.C.5","sourceIds":["cancer"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W08-Q02","blueprint":"3.D.2","sourceIds":["tacrolimus"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W08-Q03","blueprint":"3.C.2","sourceIds":["methotrexate"],"kind":"source_check","checked":"2026-10-28"},"options":["The indication and exact prescribed schedule","Whether the tablet is round","The weather at dispensing","Only the prescriber’s office hours"],"why":"Some non-oncology uses are dosed weekly. Verify the actual indication and schedule; a daily-versus-weekly error can cause serious harm."},{"audit":{"id":"W08-Q04","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W08-Q05","blueprint":"3.A","sourceIds":["tacrolimus","recon"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W08-Q06","blueprint":"3.C.5","sourceIds":["cancer"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W08-Q07","blueprint":"3.C.3","sourceIds":["tacrolimus"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W08-Q08","blueprint":"3.C.2","sourceIds":["methotrexate"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W08-Q09","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W08-Q10","blueprint":"3.D","sourceIds":["supportive"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W08-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W08-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W08-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical regimen is 40 mg/m² and the person’s body-surface area is 1.65 m². What is the calculated dose in mg?","answer":66,"unit":"mg","why":"40 mg/m² × 1.65 m² = 66 mg. This is a mathematical exercise, not a prescribing recommendation.","audit":{"id":"W08-Q14","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which steps help prevent a methotrexate schedule error? Select all that apply.","options":["Verify the exact prescribed schedule and indication","Clarify a questionable daily schedule with the prescriber","Review relevant interactions and product instructions","Assume every non-oncology regimen is taken daily"],"correct":[0,1,2],"why":"Some non-neoplastic regimens are weekly, and inadvertent daily use has caused serious harm. Verify the actual prescription.","audit":{"id":"W08-Q15","blueprint":"3.C.2","sourceIds":["methotrexate"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A new methotrexate prescription for a non-oncology condition says “daily,” while the care plan indicates a weekly regimen. What should happen?","options":["Clarify the indication and schedule before processing","Fill the daily directions because all regimens are daily","Use both schedules","Change the dose without contacting the care team"],"correct":0,"why":"Some non-oncology methotrexate regimens are weekly, and daily-versus-weekly errors can be fatal. Verify the specific plan.","audit":{"id":"W08-Q16","blueprint":"2.A.2","sourceIds":["methotrexate","mtxHandling"],"kind":"source_check","checked":"2026-10-28"}},{"q":"An immediate-release tacrolimus product is unavailable, and an extended-release product is on the shelf. What should the pharmacy do?","options":["Automatically substitute the same number of capsules","Consult the prescriber and current product guidance before any change","Assume the products have identical release and exposure","Tell the patient to alternate products daily"],"correct":1,"why":"The cited tacrolimus capsule label states that immediate-release and extended-release products are not interchangeable or substitutable.","audit":{"id":"W08-Q17","blueprint":"2.B","sourceIds":["tacrolimusForms"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A tacrolimus refill record shows a new interacting medicine and no recent level in the available chart. What is useful to review?","options":["Only the pharmacy address","Whether both products have the same color label","The current interaction, drug concentration and kidney-function monitoring plan","Whether a larger bottle can be used"],"correct":2,"why":"Tacrolimus exposure can be affected by interactions, and concentration and kidney-function monitoring may be needed.","audit":{"id":"W08-Q18","blueprint":"2.A.5","sourceIds":["tacrolimus"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A pharmacy is preparing to handle a methotrexate tablet product. Which source should guide special handling?","options":["The tablet color","A general rule that hazardous drugs never need precautions","The patient’s choice of pharmacy","Applicable hazardous-drug procedures and the product label"],"correct":3,"why":"The cited methotrexate label identifies it as cytotoxic and directs users to follow applicable special handling and disposal procedures.","audit":{"id":"W08-Q19","blueprint":"2.D","sourceIds":["mtxHandling","hazards"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C"},{"blueprint":"3.D"},{"blueprint":"3.C.2"},{"blueprint":"3.C.5"},{"blueprint":"3.C.3"}],"medicationFocus":{"title":"Methotrexate and transplant product safety","blueprint":"2.A.2 / 2.A.5 / 2.B / 2.D","intro":"Confirm the regimen and formulation before dispensing a high-risk medicine.","points":["For methotrexate, verify the indication and exact schedule. Some regimens are weekly; an unintended daily schedule can cause serious harm.","Tacrolimus immediate-release and extended-release products are not automatically interchangeable. Check the product label and treatment plan.","Methotrexate is a cytotoxic drug; follow applicable workplace handling and disposal procedures, and verify the product’s monitoring requirements."],"sourceIds":["methotrexate","mtxHandling","tacrolimusForms","tacrolimus","hazards"]},"math":{"title":"Body-surface-area dose","prompt":"A hypothetical regimen calls for 100 mg/m². If body surface area is 1.7 m², how many mg is the calculated dose?","steps":["Multiply 100 mg/m² × 1.7 m².","Cancel m² and retain mg."],"answer":"170 mg"},"sources":[{"name":"NCI cancer treatment side effects","url":"https://www.cancer.gov/about-cancer/treatment/side-effects"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"},{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"NCI: infection and neutropenia","url":"https://www.cancer.gov/about-cancer/treatment/side-effects/infection"},{"name":"MedlinePlus: methotrexate","url":"https://medlineplus.gov/druginfo/meds/a682019.html"},{"name":"MedlinePlus: tacrolimus","url":"https://www.medlineplus.gov/druginfo/meds/a601117.html"}]},{"questions":[{"audit":{"id":"W09-Q01","blueprint":"1.C.1","sourceIds":["weight"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q02","blueprint":"3.A","sourceIds":["older"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q03","blueprint":"3.C.2","sourceIds":["pregnancy"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q04","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W09-Q05","blueprint":"3.C.3","sourceIds":["supplements"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q06","blueprint":"3.C.2","sourceIds":["child","weight","syringe"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q07","blueprint":"3.A","sourceIds":["older"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q08","blueprint":"3.G","sourceIds":["syringe"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q09","blueprint":"3.C.2","sourceIds":["pregnancy"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q10","blueprint":"3.C.7","sourceIds":["adherence"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W09-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W09-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W09-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical pediatric order is 12.5 mg/kg per dose for a child weighing 16 kg. How many mg are in one dose?","answer":200,"unit":"mg","why":"12.5 mg/kg × 16 kg = 200 mg per dose. This example does not establish a safe dose for any actual child.","audit":{"id":"W09-Q14","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which checks help with a child’s oral liquid medicine? Select all that apply.","options":["Verify the current weight and units when weight matters","Check the prescribed mg dose and product concentration","Use an appropriately marked oral dosing device","Use an unmarked household spoon for accuracy"],"correct":[0,1,2],"why":"Check the patient, dose, concentration, and measuring device. A marked oral dosing device is more appropriate than an unmarked household spoon.","audit":{"id":"W09-Q15","blueprint":"3.C.2","sourceIds":["child","syringe","weight"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A pediatric prescription uses mg/kg dosing, but the most recent weight is missing and the old chart lists pounds. What should the pharmacist do?","options":["Obtain and verify a current weight and its units","Treat the old number as kilograms","Calculate from age alone without checking","Use an adult dose automatically"],"correct":0,"why":"Accurate, current weight and units are essential inputs for a weight-based pediatric order. Verify the patient and the regimen.","audit":{"id":"W09-Q16","blueprint":"2.A.2","sourceIds":["weight"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A child’s refill contains a different liquid concentration than before. What should be verified?","options":["Only the bottle color","The prescribed mg dose, new concentration and corresponding measuring instructions","That the new bottle has the same volume","That the family uses the same number of milliliters as before"],"correct":1,"why":"The volume can change when concentration changes. Verify the prescribed dose, product strength and directions before use.","audit":{"id":"W09-Q17","blueprint":"2.A.3","sourceIds":["child","syringe"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A caregiver needs to measure a small oral liquid dose. Which device is most appropriate?","options":["An unmarked kitchen spoon","A cup with no graduations","An oral dosing syringe with suitable markings","An intravenous needle and syringe used without instruction"],"correct":2,"why":"A suitably marked oral dosing device allows measurement in the intended units; avoid unmarked household spoons.","audit":{"id":"W09-Q18","blueprint":"2.A.3","sourceIds":["syringe","child"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A caregiver has just used a needle for an injection. What should happen next?","options":["Place it loose in household recycling","Flush it down a toilet","Leave it on a bedside table","Place it immediately in an appropriate sharps disposal container"],"correct":3,"why":"FDA recommends placing used sharps immediately in a sharps container and following local disposal instructions.","audit":{"id":"W09-Q19","blueprint":"2.D","sourceIds":["sharps"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C"},{"blueprint":"3.C"},{"blueprint":"3.F"},{"blueprint":"3.C"},{"blueprint":"3.A"}],"medicationFocus":{"title":"Pediatric orders, liquids and devices","blueprint":"2.A.2 / 2.A.3 / 2.D","intro":"Check the child, the order and the measurable product together.","points":["Verify a current weight and units when the dose is weight-based, along with the prescribed dose, interval and indication.","Check the concentration of the dispensed liquid each time. A changed concentration can change the volume needed for the same dose.","Use an appropriately marked oral dosing device. Used needles and other sharps belong in an appropriate sharps container, with disposal following local guidance."],"sourceIds":["weight","child","syringe","sharps"]},"math":{"title":"Liquid medicine","prompt":"A child needs a 125 mg dose. The suspension contains 125 mg in 5 mL. What volume provides one dose?","steps":["Set up 125 mg × (5 mL ÷ 125 mg).","Cancel mg and calculate."],"answer":"5 mL"},"sources":[{"name":"FDA medicine and pregnancy","url":"https://www.fda.gov/consumers/womens-health-topics/medicine-and-pregnancy"},{"name":"FDA medication safety for older adults","url":"https://www.fda.gov/consumers/consumer-updates/5-medication-safety-tips-older-adults"},{"name":"MedlinePlus drug information","url":"https://medlineplus.gov/druginformation.html"}]},{"questions":[{"audit":{"id":"W10-Q01","blueprint":"1.E","sourceIds":["study"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W10-Q02","blueprint":"1.C.8","sourceIds":["nnt"],"kind":"independent_calculation","checked":"2026-10-28"},"q":"A control event rate over the same follow-up is 20% and the treatment event rate is 10%. What is the absolute risk reduction?","why":"20% − 10% = 10 percentage points, or 0.10 as a decimal. This comparison applies to the outcome, population, and follow-up specified in the study."},{"audit":{"id":"W10-Q03","blueprint":"1.C.8","sourceIds":["nnt"],"kind":"independent_calculation","checked":"2026-10-28"},"q":"If absolute risk reduction is 0.10, what is the NNT for the study’s specified outcome and follow-up?","why":"NNT = 1 ÷ 0.10 = 10. Interpret this estimate for the population, outcome, and follow-up period studied."},{"audit":{"id":"W10-Q04","blueprint":"1.B","sourceIds":["compound"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W10-Q05","blueprint":"1.E","sourceIds":["study"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W10-Q06","blueprint":"1.C.5","sourceIds":["math"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W10-Q07","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W10-Q08","blueprint":"1.E","sourceIds":["blinding"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W10-Q09","blueprint":"1.C.8","sourceIds":["nnt"],"kind":"independent_calculation","checked":"2026-10-28"},"q":"A control event rate over the same follow-up is 15% and treatment is 10% over the same follow-up. What is ARR?","why":"15% − 10% = 5 percentage points, or 0.05. This comparison applies to the outcome, population, and follow-up specified in the study."},{"audit":{"id":"W10-Q10","blueprint":"1.C.8","sourceIds":["nnt"],"kind":"independent_calculation","checked":"2026-10-28"},"q":"If ARR is 0.05, what is the NNT for the study’s specified outcome and follow-up?","why":"NNT = 1 ÷ 0.05 = 20. Interpret this estimate for the population, outcome, and follow-up period studied."},{"audit":{"id":"W10-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W10-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W10-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"In a hypothetical one-year study, 18% of the control group and 12% of the treatment group have an event. What is the absolute risk reduction in percentage points?","answer":6,"unit":"percentage points","why":"18% − 12% = 6 percentage points over the study’s one-year follow-up.","audit":{"id":"W10-Q14","blueprint":"1.C.8","sourceIds":["math","nnt"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which statements about clinical trials are sound? Select all that apply.","options":["Randomization assigns participants by chance","Masking can limit knowledge of group assignment","The study population affects how results apply to a patient","Randomization guarantees that every possible bias is eliminated"],"correct":[0,1,2],"why":"Randomization and masking address important sources of bias, but neither eliminates all limitations; consider the population and outcomes.","audit":{"id":"W10-Q15","blueprint":"1.E","sourceIds":["study","blinding"],"kind":"source_check","checked":"2026-10-28"}},{"type":"multiple","q":"For a sterile compounded preparation, which issues need attention? Select all that apply.","options":["The formulation and compatibility","Applicable standards and appropriate training","Contamination controls and product handling","Assume the preparation is sterile because it looks clear"],"correct":[0,1,2],"why":"A calculation or a clear appearance cannot establish sterility. Use applicable current standards and product-specific information.","audit":{"id":"W10-Q16","blueprint":"1.B.2","sourceIds":["compound","sterile"],"kind":"source_check","checked":"2026-10-28"}},{"q":"An order is written “.5 mg,” and the pharmacy is rewriting it after clarification. Which notation is safer?","options":["0.5 mg","5.0 mg","50 mg","0.50.0 mg"],"correct":0,"why":"A leading zero makes the decimal point easier to see. Verify the intended dose; avoid error-prone notation.","audit":{"id":"W10-Q17","blueprint":"2.A.2","sourceIds":["abbreviation"],"kind":"source_check","checked":"2026-10-28"}},{"q":"Which FDA resource is relevant when checking whether a biological product has a biosimilar or interchangeable evaluation?","options":["A restaurant inspection list","The Purple Book","An unrelated vaccine schedule","A blank inventory sheet"],"correct":1,"why":"The FDA Purple Book lists licensed biological products, including biosimilar and interchangeable products. Check the specific product and applicable law.","audit":{"id":"W10-Q18","blueprint":"2.B","sourceIds":["purpleBook","biosimilars"],"kind":"source_check","checked":"2026-10-28"}},{"q":"Two oral products have the same drug name and strength, but one is extended-release and the other is immediate-release. What should be done?","options":["Assume they have identical administration","Substitute based on tablet color","Verify the prescribed dosage form and any proposed substitution","Mix the two formulations in one container"],"correct":2,"why":"Dosage form and release characteristics matter. Check the order, product-specific information and applicable substitution requirements.","audit":{"id":"W10-Q19","blueprint":"2.A.3","sourceIds":["metoprololER","orangeBook"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A compounded preparation has unclear storage instructions. Which is the best response?","options":["Assume room temperature is always correct","Use it until it changes color","Copy storage instructions from an unrelated product","Consult the applicable formulation, stability and storage references before assigning instructions"],"correct":3,"why":"Storage and stability are formulation-specific. Use applicable current standards and references rather than guessing from appearance.","audit":{"id":"W10-Q20","blueprint":"2.D","sourceIds":["compound"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"1.B","points":["Sterile and nonsterile preparations have different requirements. Review applicable current standards, training, formulation, equipment, documentation and contamination controls.","Check the ingredients, calculations, compatibility, stability, appropriate storage and beyond-use dating using the applicable references and standards.","Compounded drugs are generally not FDA-approved products. They can introduce risks if prepared incorrectly, so the process must be carefully controlled.","Sterile preparations need appropriate contamination controls; a clear appearance or correct calculation does not establish sterility."]},{"blueprint":"1.E"},{"blueprint":"1.E","points":["Absolute risk reduction (ARR) is the control event rate minus the treatment event rate. For an absolute reduction expressed as a decimal, number needed to treat (NNT) is 1 ÷ ARR, rounded up to a whole person. Interpret NNT for the study’s population, outcome and follow-up period.","A confidence interval shows a range of estimates consistent with a method and the observed data. Interpret it with the outcome, comparison and study design.","Use appropriate primary studies, product labeling, guidelines and trusted drug-information resources; check dates and whether the information applies to the patient."]},{"blueprint":"1.C.5"},{"blueprint":"1.C.8"}],"medicationFocus":{"title":"Product equivalence and safe notation","blueprint":"2.A.3 / 2.B / 2.D","intro":"Use the product-specific source that matches the decision.","points":["For small-molecule generics, verify strength, route and dosage form. FDA resources can help identify approved products and therapeutic-equivalence information.","The FDA Purple Book lists licensed biological products, including biosimilars and interchangeable products. Substitution also depends on applicable state rules and the prescription.","Use unambiguous dose notation and follow the product’s actual storage and handling requirements; do not infer stability from appearance."],"sourceIds":["orangeBook","purpleBook","biosimilars","abbreviation","compound"]},"math":{"title":"Absolute risk reduction and NNT","prompt":"In a hypothetical one-year study, an event occurs in 12% of the control group and 8% of the treatment group. What are the ARR and NNT?","steps":["ARR = 12% − 8% = 4 percentage points = 0.04.","NNT = 1 ÷ 0.04 = 25; round up to a whole person if needed."],"answer":"ARR = 4 percentage points; NNT = 25"},"sources":[{"name":"FDA human drug compounding","url":"https://www.fda.gov/drugs/guidance-compliance-regulatory-information/human-drug-compounding"},{"name":"NIH clinical trials and study design","url":"https://www.nei.nih.gov/eye-health-information/clinical-trials/learn-about-clinical-trials"},{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"FDA: insanitary conditions in compounding","url":"https://www.fda.gov/media/124948/download"}]},{"questions":[{"audit":{"id":"W11-Q01","blueprint":"4.A","sourceIds":["vaers"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q02","blueprint":"5.C","sourceIds":["rca"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q03","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W11-Q04","blueprint":"4.C","sourceIds":["access"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q05","blueprint":"4.A","sourceIds":["medwatch"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q06","blueprint":"5.A","sourceIds":["immediate"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q07","blueprint":"5.A","sourceIds":["error"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q08","blueprint":"5.C","sourceIds":["qi"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q09","blueprint":"4.A","sourceIds":["medwatch"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q10","blueprint":"4.C","sourceIds":["adherence"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W11-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W11-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W11-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A prescription provides 84 capsules. The directions are 2 capsules twice daily. How many days should the supply last?","answer":21,"unit":"days","why":"2 capsules × 2 times/day = 4 capsules/day; 84 ÷ 4 = 21 days.","audit":{"id":"W11-Q14","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"After a medication error that may have harmed someone, which actions support a safety response? Select all that apply.","options":["Attend to the patient’s immediate clinical needs","Examine contributing system factors","Measure whether improvement steps have their intended effect","Assume one person is the only possible cause without investigation"],"correct":[0,1,2],"why":"Address immediate patient needs, then use an appropriate systems approach to analyze the event and evaluate improvements.","audit":{"id":"W11-Q15","blueprint":"5.C","sourceIds":["immediate","rca","qi"],"kind":"source_check","checked":"2026-10-28"}},{"type":"multiple","q":"A drug recall notice arrives. Which checks are useful? Select all that apply.","options":["Compare the product and lot with the recall notice","Follow the specific recall instructions and organizational procedures","Communicate with the appropriate team about affected stock","Assume every lot of every product is always affected"],"correct":[0,1,2],"why":"Recall actions depend on the affected product, lot, and the notice. Follow the specific instructions and local procedures.","audit":{"id":"W11-Q16","blueprint":"5.B","sourceIds":["recall"],"kind":"source_check","checked":"2026-10-28"}},{"type":"multiple","q":"Which actions support privacy during a patient conversation? Select all that apply.","options":["Limit the information shared to what is appropriate","Use reasonable safeguards against being overheard","Follow applicable privacy rules and workplace procedures","Discuss patient details loudly where unnecessary listeners can hear"],"correct":[0,1,2],"why":"Reasonable safeguards and appropriate information sharing support confidentiality; exact requirements depend on the situation.","audit":{"id":"W11-Q17","blueprint":"4.D","sourceIds":["privacy"],"kind":"source_check","checked":"2026-10-28"}},{"type":"multiple","q":"Which approaches support feedback for a pharmacy learner? Select all that apply.","options":["Give feedback on observable, specific actions","Provide feedback close enough to the event to be useful","Allow the learner to reflect and practice","Wait until the end and give only a vague criticism"],"correct":[0,1,2],"why":"Specific, timely, actionable feedback and opportunities to practice are useful elements of pharmacy training.","audit":{"id":"W11-Q18","blueprint":"5.D","sourceIds":["feedback"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A pharmacy receives an isotretinoin order. What should it check regarding restricted distribution?","options":["The current iPLEDGE REMS and product-specific requirements","Whether the packaging matches another drug","Only the patient’s preferred pickup time","A years-old summary without checking for updates"],"correct":0,"why":"Isotretinoin is subject to the iPLEDGE REMS. Requirements can change, so consult the current FDA and program information.","audit":{"id":"W11-Q19","blueprint":"2.A.4","sourceIds":["rems"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A person reports mild soreness at the injection site after vaccination. Which statement is most appropriate?","options":["The soreness proves the vaccine was contaminated","Local soreness can occur; assess severity and follow product-specific guidance","All symptoms after vaccination must be caused by the vaccine","Severe or persistent symptoms never need further assessment"],"correct":1,"why":"Local injection-site reactions can occur after vaccination. Assess symptoms in context and follow product-specific guidance.","audit":{"id":"W11-Q20","blueprint":"2.C.5","sourceIds":["vaccineReactions"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A pharmacy learns about a drug recall. How should it determine whether a stocked bottle is affected?","options":["Assume all drugs from the same manufacturer are affected","Look only at the shelf location","Compare the specific product and lot with the recall notice","Use the product if the bottle appears undamaged"],"correct":2,"why":"The specific recall notice identifies the affected product and lots and gives relevant instructions.","audit":{"id":"W11-Q21","blueprint":"2.D","sourceIds":["recall"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient is prescribed an opioid together with another sedating medicine. What should the pharmacist review?","options":["Only the number of tablets in each bottle","Whether the drug names begin with the same letter","Whether the prescriptions were printed on the same day","The product warnings, patient context and prescribers’ plan"],"correct":3,"why":"Review product warnings and additive sedation and respiratory-depression risks in the context of the complete regimen.","audit":{"id":"W11-Q22","blueprint":"2.A.5","sourceIds":["opioids","label"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"4.A"},{"blueprint":"4.D"},{"blueprint":"5.A / 5.D","points":["When a medication error occurs, review contributing workflow and system factors rather than relying only on an individual to remember.","Root-cause analysis and continuous improvement examine contributing causes and possible process changes; follow organizational policy and measure whether changes help.","Review procedures for recalls, shortages, inventory, delegation, feedback and supervision. The responsible role depends on the setting and applicable rules.","When mentoring learners, use specific, timely feedback and appropriate supervision, according to the setting’s rules."]},{"blueprint":"5.C"},{"blueprint":"4.D"}],"medicationFocus":{"title":"Safety programs, recalls and reporting","blueprint":"2.A.4 / 2.C.5 / 2.D","intro":"Verify the current safety program and the exact product involved.","points":["A REMS can impose product-specific requirements. For isotretinoin, use the current iPLEDGE information and verify applicable dispensing requirements rather than relying on old summaries.","Read a recall notice carefully and compare product identifiers and lot numbers; follow the notice and organizational procedures.","VAERS accepts reports of concerning events after vaccination even when causation is uncertain; some events have mandatory reporting requirements."],"sourceIds":["rems","recall","vaccineReports"]},"math":{"title":"Inventory and days supply","prompt":"A patient uses 2 tablets per day. How many days will a supply of 60 tablets last?","steps":["Divide 60 tablets by 2 tablets per day.","Cancel tablets and retain days."],"answer":"30 days"},"sources":[{"name":"FDA MedWatch reporting","url":"https://www.fda.gov/safety/medwatch-fda-safety-information-and-adverse-event-reporting-program/reporting-serious-problems-fda"},{"name":"Vaccine Adverse Event Reporting System","url":"https://vaers.hhs.gov/"},{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"Pharmacy education: feedback study","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8006482/"}]},{"questions":[{"audit":{"id":"W12-Q01","blueprint":"S","sourceIds":["exam"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W12-Q02","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W12-Q03","blueprint":"S","sourceIds":["bulletin"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W12-Q04","blueprint":"3.A","sourceIds":["medhistory","allergy","kidney"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W12-Q05","blueprint":"S","sourceIds":["retrieval"],"kind":"study_suggestion","checked":"2026-10-28"},"q":"Which is a reasonable use of a missed-question log?","why":"A log can help organize error patterns and topics to revisit. Evidence for retrieval practice does not establish that a particular log format guarantees exam performance."},{"audit":{"id":"W12-Q06","blueprint":"3.A","sourceIds":["medhistory"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W12-Q07","blueprint":"1.C","sourceIds":["math"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W12-Q08","blueprint":"1.C","sourceIds":["rounding"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W12-Q09","blueprint":"S","sourceIds":["retrieval"],"kind":"study_suggestion","checked":"2026-10-28"},"q":"A practice question was missed because the allergy was overlooked. Which is a reasonable response?","why":"One option is to record the pattern and practice checking allergy information. This study suggestion does not guarantee future performance."},{"audit":{"id":"W12-Q10","blueprint":"S","sourceIds":["bulletin"],"kind":"source_check","checked":"2026-10-28"}},{"audit":{"id":"W12-Q11","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W12-Q12","blueprint":"1.C.3","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"audit":{"id":"W12-Q13","blueprint":"1.C.2","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}}],"added":[{"type":"numeric","q":"A hypothetical vial contains 1.2 g in 30 mL. What volume contains 200 mg? Enter a number in mL.","answer":5,"unit":"mL","why":"1.2 g = 1,200 mg, so the concentration is 40 mg/mL. 200 mg ÷ 40 mg/mL = 5 mL.","audit":{"id":"W12-Q14","blueprint":"1.C.5","sourceIds":["math"],"kind":"independent_calculation","checked":"2026-10-28"}},{"type":"multiple","q":"Which information is relevant in a patient-specific medication review? Select all that apply.","options":["The medication list and actual use","The nature of a reported allergy","Kidney function when relevant to the medicine","The medicine’s name without the patient’s circumstances"],"correct":[0,1,2],"why":"The patient’s medicines, allergy history and relevant organ function all inform medication assessment.","audit":{"id":"W12-Q15","blueprint":"3.A","sourceIds":["medhistory","allergy","kidney"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A medication list and a refill request disagree about the dose of a chronic medicine. Which step belongs in order review?","options":["Reconcile actual use and clarify the current prescribed dose","Assume the older record is correct","Use both doses simultaneously","Ignore the discrepancy if the medicine is familiar"],"correct":0,"why":"Medication reconciliation includes clarifying what the patient actually takes and resolving discrepancies with the care team.","audit":{"id":"W12-Q16","blueprint":"2.A.2","sourceIds":["recon"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A prescription says one tablet daily, but the prepared label says one tablet twice daily. What is the best next step?","options":["Allow the patient to choose either schedule","Verify the order and correct the label before dispensing","Use twice daily because it is more frequent","Remove the dosing frequency from the label"],"correct":1,"why":"The prepared directions must match the verified order. Resolve the discrepancy before the medication is dispensed.","audit":{"id":"W12-Q17","blueprint":"2.A.2","sourceIds":["recon","label"],"kind":"source_check","checked":"2026-10-28"}},{"q":"The pharmacy is considering a generic substitution. Which combination should be verified?","options":["The same tablet color and bottle size","The same manufacturer logo only","The prescribed ingredient, strength, route, formulation and applicable substitution rules","Only the cost difference"],"correct":2,"why":"Verify the product and relevant equivalence information, as well as the prescription and applicable requirements.","audit":{"id":"W12-Q18","blueprint":"2.B","sourceIds":["orangeBook"],"kind":"source_check","checked":"2026-10-28"}},{"q":"A patient requests a vaccine but has an uncertain vaccination record. What is the best first review?","options":["Assume every prior dose is valid without dates","Restart every vaccine series automatically","Choose a vaccine based only on package color","Check available records and current CDC schedule notes for that vaccine"],"correct":3,"why":"Review available vaccination records and the current schedule, including age, indications and interval guidance for the specific vaccine.","audit":{"id":"W12-Q19","blueprint":"2.C.1","sourceIds":["vaccineschedule","vaccine"],"kind":"source_check","checked":"2026-10-28"}}],"lessons":[{"blueprint":"3.C"},{"blueprint":"1.C"},{"blueprint":"S"},{"blueprint":"3.C"},{"blueprint":"1.C"}],"medicationFocus":{"title":"Bringing medication-use decisions together","blueprint":"2.A.2 / 2.A.5 / 2.B / 2.C","intro":"Use patient information, the order and the product label as one connected review.","points":["Check the indication, patient and current medication list, directions, strength, quantity, interactions and required monitoring before completing the order.","Clarify a discrepancy or potentially unsafe order rather than inventing missing information. A correct calculation does not prove a regimen is clinically appropriate.","For substitution or immunization decisions, check the product-specific and current FDA, CDC and jurisdictional requirements."],"sourceIds":["recon","label","orangeBook","vaccineschedule"]},"math":{"title":"Mixed concentration review","prompt":"A vial contains 1 g of medication in 10 mL. How many mL provide a 250 mg dose?","steps":["Convert 1 g to 1,000 mg; concentration = 1,000 mg ÷ 10 mL = 100 mg/mL.","250 mg ÷ 100 mg/mL = 2.5 mL."],"answer":"2.5 mL"},"sources":[{"name":"NABP candidate application bulletin","url":"https://read.nxtbook.com/nabp/bulletin/naplex_mpje_bulletin/"},{"name":"NABP NAPLEX content outline","url":"https://nabp.pharmacy/wp-content/uploads/NAPLEX-Content-Outline.pdf"},{"name":"NABP Pre-NAPLEX practice exam","url":"https://nabp.pharmacy/programs/practice-exams/pre-naplex/"}]}];
